window.GHIDURI={"G1": {"titlu": "Cum fac o captură de ecran", "parti": [{"t": "Pe calculator cu Windows (cel mai simplu)", "pasi": ["Apasă <b>în același timp</b> tastele <code>Windows</code> + <code>Shift</code> + <code>S</code>. Tasta <code>Windows</code> e cea cu sigla (patru pătrățele), în stânga jos. <code>Shift</code> e tasta cu săgeata în sus, de deasupra lui <code>Ctrl</code>.", "Ecranul se întunecă puțin, iar sus apare o bară mică. Lasă alegerea pe <b>Dreptunghi</b> (prima pictogramă).", "Ține apăsat butonul stâng al mouse-ului și <b>trage un dreptunghi</b> peste ce vrei să prinzi. Când dai drumul la buton, captura e gata.", "Captura e acum „în memorie” (clipboard), ca un text copiat. Mergi în Word sau în e-mail, dai click unde o vrei și apeși <code>Ctrl</code> + <code>V</code>. Apare imaginea.", "Vrei s-o salvezi ca fișier? În dreapta jos apare un mesaj mic, „Captură copiată în clipboard”. Dă click pe el, apoi pe pictograma <b>dischetă</b> (Salvare), alege folderul și scrie numele."]}, {"t": "Varianta cu o singură tastă", "pasi": ["Apasă tasta <code>PrtSc</code> (sau <code>Print Screen</code>), de obicei sus, în dreapta tastaturii. Pe Windows 11 se deschide aceeași bară de captură. Pe Windows 10 se copiază tot ecranul, iar tu lipești cu <code>Ctrl</code> + <code>V</code>."]}, {"t": "Pe telefon", "pasi": ["<b>Android</b> (Samsung, Xiaomi etc.): apasă <b>în același timp</b> butonul de pornire și butonul de volum în jos, o secundă. Ecranul clipește: captura e în <b>Galerie</b>.", "<b>iPhone fără buton rotund</b>: butonul din lateral + volum sus, în același timp. <b>iPhone cu buton rotund</b>: butonul rotund + butonul de pornire."]}, {"t": "Dacă nu merge", "pasi": ["Nu se întâmplă nimic la <code>Windows</code> + <code>Shift</code> + <code>S</code>? Apasă tastele pe rând și ține-le apăsate până la ultima. Sau caută în meniul Start „<b>Instrument de decupare</b>” (Snipping Tool) și apasă <b>Nou</b>.", "Pe laptop, <code>PrtSc</code> poate cere și tasta <code>Fn</code> (apeși <code>Fn</code> + <code>PrtSc</code>)."]}]}, "G2": {"titlu": "Cum lipesc o captură într-un document Word", "parti": [{"t": "Pașii", "pasi": ["Fă captura (ghidul <b>G1</b>). Nu mai trebuie salvată: e deja în memorie.", "Deschide documentul Word și dă click <b>exact în locul</b> unde vrei imaginea, de exemplu pe un rând gol de la final.", "Apasă <code>Ctrl</code> + <code>V</code>. Imaginea apare.", "E prea mare? Dă click pe ea: apar cerculețe în colțuri. Prinde un <b>colț</b> și trage spre interior. Din colț, imaginea își păstrează proporțiile.", "Salvează documentul cu <code>Ctrl</code> + <code>S</code>."]}, {"t": "Dacă nu merge", "pasi": ["Nu se lipește nimic? Captura nu s-a făcut. Mai fă o dată pasul din ghidul G1 și lipește imediat după."]}]}, "G3": {"titlu": "Cum salvez un fișier cu numele corect și unde îl găsesc", "parti": [{"t": "Salvarea", "pasi": ["În Word, Excel sau PowerPoint apasă <b>Fișier</b> (File) → <b>Salvare ca</b> (Save As) → <b>Răsfoire</b> (Browse). Pe unele versiuni: <b>Acest PC</b> (This PC).", "În stânga ferestrei alege <b>Documente</b> (Documents). E un loc ușor de ținut minte.", "În căsuța <b>Nume fișier</b> (File name) șterge ce scrie și pune numele cerut, de exemplu <code>E14_Word_Popescu_Maria</code>. <b>Fără diacritice și fără spații</b>: în loc de spațiu pui liniuță jos <code>_</code> (<code>Shift</code> + tasta minus).", "Apasă <b>Salvare</b> (Save). De acum, la fiecare modificare apeși doar <code>Ctrl</code> + <code>S</code>."]}, {"t": "Unde îl găsesc mai târziu", "pasi": ["Apasă <code>Windows</code> + <code>E</code>: se deschide <b>Explorer</b> (dosarul cu fișiere). În stânga dai click pe <b>Documente</b>.", "Fișierele descărcate de pe site ajung, de obicei, în <b>Descărcări</b> (Downloads), tot din stânga.", "Nu-l găsești? Sus în dreapta, în căsuța de căutare din Explorer, scrie o parte din nume (de exemplu <code>E14</code>)."]}, {"t": "De ce fără diacritice în nume", "pasi": ["Unele programe de e-mail și unele servere „strică” literele ă, î, ș, ț din numele fișierelor. Textul <b>din interiorul</b> documentului îl scrii, firește, cu diacritice."]}]}, "G4": {"titlu": "Cum salvez un document ca PDF", "parti": [{"t": "Din Word sau PowerPoint", "pasi": ["Cu documentul deschis: <b>Fișier</b> (File) → <b>Salvare ca</b> (Save As) → <b>Răsfoire</b> (Browse).", "Jos, la <b>Tip fișier</b> (Save as type), deschide lista și alege <b>PDF (*.pdf)</b>.", "Verifică numele și apasă <b>Salvare</b> (Save). Documentul original rămâne neschimbat: acum ai două fișiere, <code>.docx</code> (sau <code>.pptx</code>) și <code>.pdf</code>."]}, {"t": "Varianta 2", "pasi": ["<b>Fișier</b> → <b>Export</b> → <b>Creare document PDF/XPS</b> → <b>Publicare</b>."]}, {"t": "Verifică", "pasi": ["Deschide PDF-ul (dublu click). Trebuie să arate exact ca documentul. Dacă vezi pagini goale sau tăiate, întoarce-te în Word și repară, apoi salvează din nou ca PDF."]}]}, "G5": {"titlu": "Cum atașez un fișier la un e-mail", "parti": [{"t": "Outlook (aplicația sau outlook.com)", "pasi": ["Apasă <b>E-mail nou</b> (New mail).", "Apasă pe <b>agrafă</b>, <b>Atașare fișier</b> (Attach File) → <b>Răsfoiți acest computer</b> (Browse this computer).", "Alege fișierul (de obicei din <b>Documente</b>) → <b>Deschidere</b>. Fișierul apare ca o casetă mică sub subiect."]}, {"t": "Gmail sau Yahoo", "pasi": ["<b>Scrieți</b> (Compose), apoi, jos, pictograma <b>agrafă</b>. Alegi fișierul → <b>Deschidere</b>."]}, {"t": "De pe telefon (aplicația Gmail)", "pasi": ["Scrii mesajul nou, apoi sus apeși <b>agrafa</b> → <b>Atașează fișierul</b> → alegi fișierul din <b>Descărcări</b> sau <b>Fișiere</b>."]}, {"t": "Dacă nu merge", "pasi": ["Fișierul e prea mare (peste 20–25 MB)? Salvează-l pe OneDrive și trimite un link (ghidul <b>G9</b>).", "Nu vezi fișierul în listă? Uită-te în <b>Descărcări</b> sau caută-l după nume (ghidul <b>G3</b>)."]}]}, "G6": {"titlu": "Cum trimit tema pe e-mail", "parti": [{"t": "Pașii", "pasi": ["<b>La</b> (To): <code>bogdan@pandapc.ro</code>", "<b>Subiect</b>: exact textul din pagina exercițiului. Apasă butonul <b>Copiază</b> de lângă el, apoi în e-mail, la Subiect, <code>Ctrl</code> + <code>V</code>. Înlocuiește „Nume Prenume” cu numele tău.", "<b>Mesaj</b>: 1–2 rânduri, de exemplu: „Bună ziua, vă trimit exercițiul E04. Mulțumesc!” și numele tău.", "<b>Atașează</b> fișierul (ghidul <b>G5</b>) și verifică dacă apare caseta cu numele lui.", "Apasă <b>Trimitere</b> (Send). Verifică în <b>Elemente trimise</b> (Sent) că e-mailul a plecat."]}, {"t": "Bine de știut", "pasi": ["Nu există termen-limită: trimiți când ai terminat. Rezolvarea apare pe site a doua zi după ora exercițiului, de la 17:00."]}]}, "G7": {"titlu": "Cum folosesc „Verificare accesibilitate” (Word, PowerPoint)", "parti": [{"t": "Pașii", "pasi": ["Fila <b>Revizuire</b> (Review) → <b>Verificare accesibilitate</b> (Check Accessibility). Pe versiunile noi butonul poate fi sub săgeata de lângă el.", "În dreapta se deschide un panou cu <b>Erori</b> (Errors) și <b>Avertismente</b> (Warnings).", "Dă click pe o problemă: programul îți arată unde e și, dedesubt, <b>Remedieri recomandate</b> (Recommended Actions). Alegi una și se rezolvă (de exemplu adaugi text alternativ).", "Când lista e goală, documentul trece verificarea de bază."]}, {"t": "Ce înseamnă cele mai dese mesaje", "pasi": ["<b>Text alternativ lipsă</b>: o imagine nu are descriere pentru cititorul de ecran.", "<b>Titlu lipsă</b> (în PowerPoint): diapozitivul nu are casetă de titlu.", "<b>Contrast insuficient</b>: textul se citește greu pe fundal."]}]}, "G8": {"titlu": "Scurtăturile de tastatură de bază", "parti": [{"t": "Pentru orice program", "pasi": ["<code>Ctrl</code> + <code>C</code> copiază · <code>Ctrl</code> + <code>V</code> lipește · <code>Ctrl</code> + <code>X</code> taie · <code>Ctrl</code> + <code>Z</code> anulează ultima acțiune (salvatorul tuturor).", "<code>Ctrl</code> + <code>S</code> salvează · <code>Ctrl</code> + <code>P</code> tipărește · <code>Ctrl</code> + <code>F</code> caută un cuvânt.", "<code>Alt</code> + <code>Tab</code> trece de la o fereastră la alta."]}, {"t": "Fără mouse", "pasi": ["<code>Tab</code> te duce la următorul buton sau câmp, <code>Shift</code> + <code>Tab</code> la cel de dinainte. <code>Enter</code> apasă butonul ales, iar <code>Spațiu</code> bifează o căsuță.", "Săgețile te mută într-o listă sau într-un meniu."]}, {"t": "Accesibilitate", "pasi": ["<code>Windows</code> + <code>+</code> pornește <b>Lupa</b> (Magnifier), iar <code>Windows</code> + <code>Esc</code> o oprește.", "<code>Ctrl</code> + <code>Windows</code> + <code>Enter</code> pornește și oprește <b>Naratorul</b> (cititorul de ecran din Windows).", "În browser, <code>Ctrl</code> + <code>+</code> mărește pagina, <code>Ctrl</code> + <code>-</code> o micșorează, <code>Ctrl</code> + <code>0</code> o readuce la normal."]}]}, "G9": {"titlu": "Cum partajez un fișier din OneDrive", "parti": [{"t": "Pașii (OneDrive pe web sau în Explorer)", "pasi": ["Click dreapta pe fișier → <b>Partajare</b> (Share). Pe web: selectezi fișierul și apeși <b>Partajare</b> sus.", "În fereastră, uită-te la rândul care spune <b>cine</b> are acces, de exemplu „Oricine are linkul poate edita”. Dă click pe el (sau pe rotița <b>Setări</b>).", "Alege <b>Persoane specifice</b> (pe unele versiuni: <b>Persoanele pe care le alegeți</b>). Așa, linkul merge doar la cei pe care îi scrii tu.", "Alege <b>ce pot face</b>: <b>Poate vizualiza</b> (doar citește) sau <b>Poate edita</b> (poate modifica). Implicit alege <b>vizualizare</b>.", "Scrie adresa de e-mail a persoanei, apoi <b>Trimitere</b> (Send) sau <b>Copiere link</b> (Copy link)."]}, {"t": "Bine de știut", "pasi": ["La <b>Persoane specifice</b> nu există parolă și dată de expirare. Acestea apar doar la „Oricine are linkul”, și doar pe unele conturi.", "Poți schimba sau opri accesul oricând, din același meniu: <b>Gestionare acces</b> (Manage access)."]}]}, "G10": {"titlu": "Cum văd cât spațiu ocupă OneDrive, telefonul sau căsuța de e-mail", "parti": [{"t": "OneDrive", "pasi": ["Pe web: intră pe onedrive.live.com (sau OneDrive-ul de la serviciu). Jos în stânga vezi „<b>… GB folosiți din …</b>”.", "Pe calculator: click pe norișorul OneDrive din dreapta jos (lângă ceas) → rotița → <b>Setări</b> (Settings) → <b>Cont</b> (Account)."]}, {"t": "Telefonul", "pasi": ["<b>Android</b>: <b>Setări</b> → <b>Stocare</b> (pe Samsung: <b>Setări</b> → <b>Îngrijire dispozitiv</b> / Întreținere baterie și dispozitiv → <b>Stocare</b>). Numele exacte diferă de la un telefon la altul.", "<b>iPhone</b>: <b>Configurări</b> → <b>General</b> → <b>Spațiu iPhone</b>."]}, {"t": "E-mailul", "pasi": ["<b>Gmail</b>: jos, sub lista de mesaje, vezi „… GB din 15 GB”.", "<b>Outlook.com</b>: <b>Setări</b> (rotița) → <b>General</b> → <b>Stocare</b> (Storage).", "Caută e-mailurile cu atașamente mari: în Gmail scrii în căutare <code>has:attachment larger:10M</code>."]}]}};
